export function matchFallbackTopic(question: string): Topic | null {
  const q = question.toLowerCase();
  let best: { topic: Topic; score: number } | null = null;
  for (const t of FALLBACK_TOPICS) {
    const score = t.keywords.reduce((s, k) => (q.includes(k) ? s + k.length : s), 0);
    if (score > 0 && (!best || score > best.score)) best = { topic: t, score };
  }
  return best?.topic ?? null;
}

export function isFinanceQuestion(q: string) {
  return /(profit|income|revenue|expense|spent|spend|cost|earn|sales|money|financial|loss)/i.test(q);
}
